// pages/Feed.jsx
import React, { useEffect, useState, useRef } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import ReviewCard from '../components/ReviewCard';
import PostEditor from '../components/PostEditor';
import {
  fetchReviews,
  createReview as apiCreateReview,
  updateReview as apiUpdateReview,
  deleteReview as apiDeleteReview,
  addComment as apiAddComment,
  removeComment as apiRemoveComment
} from '../api/reviewApi';
import sampleReviews from '../data/sampleReviews';

function Feed() {
  const navigate = useNavigate();
  const reviewSectionRef = useRef(null);

  const [reviews, setReviews] = useState([]);
  const [editingId, setEditingId] = useState(null);
  const [editingItem, setEditingItem] = useState(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [isSearchFocused, setIsSearchFocused] = useState(false);
  const [activeCategory, setActiveCategory] = useState('all');
  const [reviewType, setReviewType] = useState('all');

  const currentUser = (() => { try { return JSON.parse(localStorage.getItem('user') || 'null'); } catch (e) { return null; } })();
  const currentUserName = currentUser ? (currentUser.username || currentUser.name || currentUser.email) : null;

  useEffect(() => {
    const load = async () => {
      try {
        const res = await fetchReviews();
        setReviews(res.data || sampleReviews);
      } catch (e) {
        setReviews(sampleReviews);
      }
    };
    load();
  }, []);

  const handleSubmit = async (payload) => {
    if (currentUserName) payload.author = { username: currentUserName };
    if (editingId) {
      const res = await apiUpdateReview(editingId, payload, currentUserName);
      setReviews(prev => prev.map(r => r._id === editingId ? res.data : r));
      setEditingId(null);
      setEditingItem(null);
    } else {
      const res = await apiCreateReview(payload);
      setReviews(prev => [res.data, ...prev]);
    }
  };

  const handleDelete = async (id) => {
    if (!window.confirm('정말 삭제할까요?')) return;
    await apiDeleteReview(id, currentUserName);
    setReviews(prev => prev.filter(r => r._id !== id));
  };

  const handleAddComment = async (reviewId, text) => {
    const res = await apiAddComment(reviewId, text, currentUserName || '익명');
    setReviews(prev => prev.map(r => r._id === reviewId ? { ...r, comments: [...(r.comments || []), res.data] } : r));
  };

  const handleDeleteComment = async (reviewId, commentId) => {
    await apiRemoveComment(reviewId, commentId, currentUserName);
    setReviews(prev => prev.map(r => r._id === reviewId ? { ...r, comments: (r.comments || []).filter(c => c._id !== commentId) } : r));
  };

  const filteredReviews = (() => {
    let filtered = activeCategory === 'all' ? reviews : reviews.filter(r => r.category === activeCategory);
    if (reviewType === 'photo') filtered = filtered.filter(r => r.images && r.images.length > 0);
    if (reviewType === 'text') filtered = filtered.filter(r => !r.images || r.images.length === 0);
    if (searchQuery.trim()) {
      const query = searchQuery.toLowerCase().trim();
      filtered = filtered.filter(r =>
        r.brand?.toLowerCase().includes(query) ||
        r.product?.toLowerCase().includes(query) ||
        r.title?.toLowerCase().includes(query) ||
        r.text?.toLowerCase().includes(query) ||
        r.tags?.some(tag => tag.toLowerCase().includes(query))
      );
    }
    return filtered;
  })();

  return (
    <div style={{ minHeight: '100vh', background: 'linear-gradient(180deg, #fff 0%, #fff5f7 30%, #faf5ff 100%)' }}>
      <style>{`
        @keyframes float { 0%,100%{transform:translateY(0)} 50%{transform:translateY(-10px)} }
        @keyframes bounce { 0%,100%{transform:translateY(0)} 50%{transform:translateY(-5px)} }
      `}</style>

      <div className="container page-enter" style={{ paddingTop: 24, paddingBottom: 40 }}>
        {/* 헤더 */}
        <header style={{ marginBottom: 24, background: 'rgba(255,255,255,0.9)', borderRadius: 20, padding: '18px 20px', boxShadow: '0 8px 24px rgba(0,0,0,0.06)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <div>
            <div style={{ fontSize: 26, fontWeight: 900, display: 'flex', alignItems: 'center', gap: 10, color: '#ff4d88' }}>
              <span style={{ animation: 'bounce 2s ease-in-out infinite' }}>📝</span> 뷰티 리뷰
            </div>
            <div style={{ color: '#666', marginTop: 4, fontSize: 14 }}>취향에 맞는 제품을 찾아보세요</div>
          </div>
          <div style={{ display: 'flex', gap: 8 }}>
            <button onClick={() => navigate('/promo')} className="btn" style={{ background: '#fff', border: '1px solid #ffd7e4', color: '#ff4d88' }}>쿠폰센터</button>
            <button onClick={() => reviewSectionRef.current?.scrollIntoView({ behavior: 'smooth' })} className="btn btn-primary">리뷰 보기</button>
          </div>
        </header>

        {/* 작성기 */}
        <div style={{ marginBottom: 20 }}>
          <PostEditor
            initial={editingItem}
            onCancel={() => { setEditingId(null); setEditingItem(null); }}
            onSubmit={handleSubmit}
          />
        </div>

        {/* 필터 */}
        <div style={{ marginBottom: 16 }}>
          <div style={{ display: 'flex', gap: 10, flexWrap: 'wrap', marginBottom: 10 }}>
            <input
              type="text"
              placeholder="브랜드, 제품, 태그 검색"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              onFocus={() => setIsSearchFocused(true)}
              onBlur={() => setIsSearchFocused(false)}
              style={{
                flex: 1,
                minWidth: 240,
                padding: '10px 12px',
                borderRadius: 12,
                border: isSearchFocused ? '2px solid #ff4d88' : '1px solid #e5e7eb'
              }}
            />
            {searchQuery && (
              <button className="btn" onClick={() => setSearchQuery('')} style={{ background: '#fff5f8', border: '1px solid #ffd7e4', color: '#ff4d88' }}>
                초기화
              </button>
            )}
          </div>
          <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
            {[
              { id: 'all', name: '전체' },
              { id: 'skincare', name: '스킨케어' },
              { id: 'makeup', name: '메이크업' },
              { id: 'bodycare', name: '바디케어' },
              { id: 'fashion', name: '패션' }
            ].map(cat => (
              <button
                key={cat.id}
                onClick={() => setActiveCategory(cat.id)}
                className="btn"
                style={{
                  border: activeCategory === cat.id ? '2px solid #ff4d88' : '1px solid #e5e7eb',
                  background: activeCategory === cat.id ? '#fff0f6' : '#fff'
                }}
              >
                {cat.name}
              </button>
            ))}

            {[{ id: 'all', name: '전체' }, { id: 'photo', name: '포토' }, { id: 'text', name: '텍스트' }].map(type => (
              <button
                key={type.id}
                onClick={() => setReviewType(type.id)}
                className="btn"
                style={{
                  border: reviewType === type.id ? '2px solid #a855f7' : '1px solid #e5e7eb',
                  background: reviewType === type.id ? '#f5f0ff' : '#fff'
                }}
              >
                {type.name}
              </button>
            ))}
          </div>
        </div>

        {/* 리뷰 리스트 */}
        <div ref={reviewSectionRef}>
          <div style={{ color: '#888', fontSize: 13, marginBottom: 12 }}>
            {filteredReviews.length}개의 리뷰 {searchQuery && <span style={{ marginLeft: 8, color: '#ff4d88' }}>"{searchQuery}"</span>}
          </div>
          <div className="reviews-grid">
            {filteredReviews.length > 0 ? filteredReviews.map(r => (
              <ReviewCard
                key={r._id}
                id={r._id}
                username={r.author?.username || '익명'}
                brand={r.brand}
                product={r.product}
                title={r.title}
                text={r.text}
                images={r.images}
                createdAt={r.createdAt}
                likes={r.likes}
                comments={r.comments?.length || 0}
                commentsList={r.comments || []}
                tags={r.tags}
                rating={r.rating}
                canEdit={currentUserName && ((r.author && ((r.author.username && r.author.username === currentUserName) || (r.author.name && r.author.name === currentUserName))) || (typeof r.author === 'string' && r.author === currentUserName))}
                onEdit={(id) => {
                  setEditingId(id);
                  setEditingItem(r);
                  window.scrollTo({ top: 0, behavior: 'smooth' });
                }}
                onDelete={handleDelete}
                onAddComment={handleAddComment}
                onDeleteComment={handleDeleteComment}
              />
            )) : (
              <div style={{ gridColumn: 'span 3', textAlign: 'center', padding: '40px 20px', background: '#fff5f7', borderRadius: 16 }}>
                <div style={{ fontSize: 36, marginBottom: 10 }}>🔍</div>
                <div style={{ fontSize: 16, fontWeight: 700, marginBottom: 6 }}>검색 결과가 없습니다</div>
                <button className="btn btn-primary" onClick={() => setSearchQuery('')}>전체 리뷰 보기</button>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

export default Feed;
